   HAVEN — Modern Ecommerce Stylesheet
   ========================================================= */

/* ----- Reset & Tokens ----- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-brand:       #1a1a2e;
  --color-accent:      #e94560;
  --color-accent-dark: #c73652;
  --color-surface:     #ffffff;
  --color-bg:          #f6f6f8;
  --color-bg-2:        #eeeef3;
  --color-text:        #1a1a2e;
  --color-text-muted:  #5a5a78;
  --color-border:      #dcdce8;
  --color-badge-sale:  #e94560;
  --color-badge-new:   #0e9f6e;
  --color-focus:       #1a6bff;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-pill: 9999px;

  --shadow-sm: 0 1px 3px rgba(26,26,46,.08), 0 1px 2px rgba(26,26,46,.04);
  --shadow-md: 0 4px 16px rgba(26,26,46,.10), 0 2px 6px rgba(26,26,46,.06);
  --shadow-lg: 0 12px 40px rgba(26,26,46,.14), 0 4px 12px rgba(26,26,46,.08);

  --transition: 200ms ease;
  --max-w: 1280px;
}

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* ----- Skip Link ----- */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .75rem 1.25rem;
  background: var(--color-brand);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; outline: 3px solid var(--color-focus); outline-offset: 2px; }

/* ----- Focus styles ----- */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* =========================================================
   ANNOUNCEMENT BAR
   ========================================================= */
.announcement-bar {
  background: var(--color-brand);
  color: #fff;
  text-align: center;
  padding: .6rem 1rem;
  font-size: .8125rem;
  font-weight: 500;
  letter-spacing: .02em;
}
.announcement-bar a { text-decoration: underline; text-underline-offset: 3px; color: #fff; }

/* =========================================================
   HEADER
   ========================================================= */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 64px;
  gap: 1rem;
}

/* Logo */
.site-logo {
  justify-self: start;
  display: flex;
  align-items: center;
  gap: .5rem;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: .04em;
  color: var(--color-brand);
}
.site-logo svg { color: var(--color-accent); }

/* Primary Nav */
.primary-nav { justify-self: center; }
.primary-nav ul { display: flex; gap: 2rem; }
.primary-nav a {
  font-size: .9375rem;
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition);
  padding: .25rem 0;
  position: relative;
}
.primary-nav a::after {
  content: '';
  position: absolute;
  bottom: -2px; left: 0; right: 0;
  height: 2px;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}
.primary-nav a:hover, .primary-nav a[aria-current="page"] { color: var(--color-brand); }
.primary-nav a:hover::after, .primary-nav a[aria-current="page"]::after { transform: scaleX(1); }

/* Header Actions */
.header-actions {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: .5rem;
}

.icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--color-bg-2); color: var(--color-brand); }

.cart-btn { position: relative; }
.cart-count {
  position: absolute;
  top: 2px; right: 2px;
  min-width: 18px; height: 18px;
  padding: 0 4px;
  background: var(--color-accent);
  color: #fff;
  font-size: .6875rem;
  font-weight: 700;
  border-radius: var(--radius-pill);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

/* Search bar */
.search-form {
  display: flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-bg);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-pill);
  padding: .25rem .75rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.search-form:focus-within {
  border-color: var(--color-focus);
  box-shadow: 0 0 0 3px rgba(26,107,255,.18);
}
.search-form input {
  background: none;
  border: none;
  outline: none;
  font-size: .875rem;
  color: var(--color-text);
  width: 180px;
}
.search-form input::placeholder { color: var(--color-text-muted); }
.search-form button {
  color: var(--color-text-muted);
  display: flex;
  padding: 0;
  transition: color var(--transition);
}
.search-form button:hover { color: var(--color-brand); }

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* =========================================================
   HERO SECTION
   ========================================================= */
.hero {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 55%, #0f3460 100%);
  color: #fff;
  overflow: hidden;
  position: relative;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 5rem 1.5rem;
  gap: 3rem;
  min-height: 560px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .8125rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1rem;
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 24px; height: 2px;
  background: var(--color-accent);
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 1.25rem;
}
.hero-title em { font-style: normal; color: var(--color-accent); }

.hero-desc {
  font-size: 1.0625rem;
  color: rgba(255,255,255,.75);
  max-width: 440px;
  margin-bottom: 2rem;
  line-height: 1.7;
}

.hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .8125rem 1.75rem;
  border-radius: var(--radius-pill);
  font-size: .9375rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
  box-shadow: 0 4px 14px rgba(233,69,96,.4);
}
.btn-primary:hover { background: var(--color-accent-dark); box-shadow: 0 6px 20px rgba(233,69,96,.5); }

.btn-outline-light {
  background: transparent;
  color: #fff;
  border: 2px solid rgba(255,255,255,.4);
}
.btn-outline-light:hover { background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.7); }

.btn-outline {
  background: transparent;
  color: var(--color-brand);
  border: 2px solid var(--color-border);
}
.btn-outline:hover { background: var(--color-bg-2); border-color: var(--color-brand); }

.btn-sm {
  padding: .5rem 1.25rem;
  font-size: .875rem;
}

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-image-frame {
  position: relative;
  width: 100%;
  max-width: 460px;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.hero-image-frame img {
  width: 100%; height: 100%;
  object-fit: cover;
}

.hero-badge {
  position: absolute;
  bottom: 1.5rem;
  left: -1.5rem;
  background: var(--color-surface);
  color: var(--color-text);
  border-radius: var(--radius-md);
  padding: .875rem 1.25rem;
  box-shadow: var(--shadow-lg);
  min-width: 160px;
}
.hero-badge-label {
  font-size: .75rem;
  font-weight: 500;
  color: var(--color-text-muted);
  margin-bottom: .2rem;
}
.hero-badge-value {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-accent);
}

/* Hero decorative shapes */
.hero::before {
  content: '';
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(233,69,96,.15) 0%, transparent 70%);
  top: -100px; right: -100px;
  pointer-events: none;
}

/* =========================================================
   SECTION SCAFFOLDING
   ========================================================= */
.section { padding: 5rem 1.5rem; }
.section-inner { max-width: var(--max-w); margin: 0 auto; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}

.section-kicker {
  display: block;
  font-size: .8125rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .35rem;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.625rem, 3vw, 2.25rem);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-brand);
}

.view-all-link {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  font-size: .9375rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  transition: gap var(--transition), color var(--transition);
}
.view-all-link:hover { gap: .625rem; color: var(--color-accent-dark); }

/* =========================================================
   CATEGORY STRIP
   ========================================================= */
.categories { background: var(--color-surface); padding: 2.5rem 1.5rem; }

.categories-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1rem;
  max-width: var(--max-w);
  margin: 0 auto;
}

.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .875rem;
  padding: 1.5rem 1rem;
  background: var(--color-bg);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  text-align: center;
  transition: background var(--transition), border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  color: var(--color-text);
}
.category-card:hover {
  background: var(--color-surface);
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.category-icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-md);
  background: var(--color-brand);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
}
.category-card:hover .category-icon { background: var(--color-accent); }
.category-icon svg { transition: color var(--transition); }

.category-name {
  font-weight: 600;
  font-size: .9375rem;
}
.category-count {
  font-size: .8125rem;
  color: var(--color-text-muted);
}

/* =========================================================
   PRODUCT GRID
   ========================================================= */
.products-section { background: var(--color-bg); }

.filter-bar {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.filter-btn {
  padding: .5rem 1.125rem;
  border-radius: var(--radius-pill);
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}
.filter-btn:hover, .filter-btn[aria-pressed="true"] {
  background: var(--color-brand);
  color: #fff;
  border-color: var(--color-brand);
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

/* Product Card */
.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  border: 1.5px solid var(--color-border);
  overflow: hidden;
  display: flex;
  flex-direction: column;
