+  padding: .875rem 1.25rem;
+  box-shadow: var(--shadow-lg);
+  min-width: 160px;
+}
+.hero-badge-label {
+  font-size: .75rem;
+  font-weight: 500;
+  color: var(--color-text-muted);
+  margin-bottom: .2rem;
+}
+.hero-badge-value {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+
+/* Hero decorative shapes */
+.hero::before {
+  content: '';
+  position: absolute;
+  width: 500px; height: 500px;
+  border-radius: 50%;
+  background: radial-gradient(circle, rgba(233,69,96,.15) 0%, transparent 70%);
+  top: -100px; right: -100px;
+  pointer-events: none;
+}
+
+/* =========================================================
+   SECTION SCAFFOLDING
+   ========================================================= */
+.section { padding: 5rem 1.5rem; }
+.section-inner { max-width: var(--max-w); margin: 0 auto; }
+
+.section-header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 1rem;
+  margin-bottom: 2.5rem;
+  flex-wrap: wrap;
+}
+
+.section-kicker {
+  display: block;
+  font-size: .8125rem;
+  font-weight: 600;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .35rem;
+}
+
+.section-title {
+  font-family: var(--font-display);
+  font-size: clamp(1.625rem, 3vw, 2.25rem);
+  font-weight: 700;
+  line-height: 1.2;
+  color: var(--color-brand);
+}
+
+.view-all-link {
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  font-size: .9375rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  white-space: nowrap;
+  transition: gap var(--transition), color var(--transition);
+}
+.view-all-link:hover { gap: .625rem; color: var(--color-accent-dark); }
+
+/* =========================================================
+   CATEGORY STRIP
+   ========================================================= */
+.categories { background: var(--color-surface); padding: 2.5rem 1.5rem; }
+
+.categories-grid {
+  display: grid;
+  grid-template-columns: repeat(5, 1fr);
+  gap: 1rem;
+  max-width: var(--max-w);
+  margin: 0 auto;
+}
+
+.category-card {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .875rem;
+  padding: 1.5rem 1rem;
+  background: var(--color-bg);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-md);
+  text-align: center;
+  transition: background var(--transition), border-color var(--transition), box-shadow var(--transition), transform var(--transition);
+  color: var(--color-text);
+}
+.category-card:hover {
+  background: var(--color-surface);
+  border-color: var(--color-accent);
+  box-shadow: var(--shadow-md);
+  transform: translateY(-3px);
+}
+
+.category-icon {
+  width: 56px; height: 56px;
+  border-radius: var(--radius-md);
+  background: var(--color-brand);
+  color: #fff;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.category-card:hover .category-icon { background: var(--color-accent); }
+.category-icon svg { transition: color var(--transition); }
+
+.category-name {
+  font-weight: 600;
+  font-size: .9375rem;
+}
+.category-count {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+}
+
+/* =========================================================
+   PRODUCT GRID
+   ========================================================= */
+.products-section { background: var(--color-bg); }
+
+.filter-bar {
+  display: flex;
+  gap: .5rem;
+  flex-wrap: wrap;
+  margin-bottom: 2rem;
+}
+
+.filter-btn {
+  padding: .5rem 1.125rem;
+  border-radius: var(--radius-pill);
+  font-size: .875rem;
+  font-weight: 500;
+  color: var(--color-text-muted);
+  background: var(--color-surface);
+  border: 1.5px solid var(--color-border);
+  transition: background var(--transition), color var(--transition), border-color var(--transition);
+}
+.filter-btn:hover, .filter-btn[aria-pressed="true"] {
+  background: var(--color-brand);
+  color: #fff;
+  border-color: var(--color-brand);
+}
+
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 1.5rem;
+}
+
+/* Product Card */
+.product-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-md);
+  border: 1.5px solid var(--color-border);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.product-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
+
+.product-card-image {
+  position: relative;
+  aspect-ratio: 3/4;
+  overflow: hidden;
+  background: var(--color-bg-2);
+}
+.product-card-image img {
+  width: 100%; height: 100%;
+  object-fit: cover;
+  transition: transform 400ms ease;
+}
+.product-card:hover .product-card-image img { transform: scale(1.05); }
+
+.product-card-badges {
+  position: absolute;
+  top: .75rem; left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+  z-index: 1;
+}
+.badge {
+  display: inline-block;
+  padding: .25rem .625rem;
+  border-radius: var(--radius-pill);
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .03em;
+  text-transform: uppercase;
+}
+.badge-sale { background: var(--color-badge-sale); color: #fff; }
+.badge-new  { background: var(--color-badge-new);  color: #fff; }
+
+.product-card-wishlist {
+  position: absolute;
+  top: .75rem; right: .75rem;
+  width: 36px; height: 36px;
+  background: rgba(255,255,255,.9);
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--color-text-muted);
+  backdrop-filter: blur(4px);
+  transition: background var(--transition), color var(--transition);
+  z-index: 1;
+}
+.product-card-wishlist:hover { background: #fff; color: var(--color-accent); }
+.product-card-wishlist[aria-pressed="true"] { color: var(--color-accent); }
+
+.product-card-body {
+  padding: 1rem 1rem 1.25rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+}
+.product-card-brand {
+  font-size: .75rem;
+  font-weight: 500;
+  letter-spacing: .05em;
+  text-transform: uppercase;
+  color: var(--color-text-muted);
+}
+.product-card-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  line-height: 1.35;
+  color: var(--color-text);
+}
+.product-card-rating {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+}
+.stars { color: #f59e0b; display: flex; gap: 1px; }
+
+.product-card-footer {
+  padding: 0 1rem 1rem;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: .5rem;
+}
+.product-price {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+}
+.price-current {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-brand);
+}
+.price-original {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.price-current.is-sale { color: var(--color-accent); }
+
+.add-to-cart-btn {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 38px; height: 38px;
+  border-radius: var(--radius-sm);
+  background: var(--color-brand);
+  color: #fff;
+  flex-shrink: 0;
+  transition: background var(--transition), transform var(--transition);
+}
+.add-to-cart-btn:hover { background: var(--color-accent); transform: scale(1.08); }
+
+/* =========================================================
+   DEALS SECTION
+   ========================================================= */
+.deals-section { background: var(--color-brand); color: #fff; }
+.deals-section .section-kicker { color: var(--color-accent); }
+.deals-section .section-title { color: #fff; }
+.deals-section .view-all-link { color: rgba(255,255,255,.7); }
+.deals-section .view-all-link:hover { color: #fff; }
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.deal-card {
+  background: rgba(255,255,255,.05);
+  border: 1px solid rgba(255,255,255,.1);
+  border-radius: var(--radius-md);
+  display: flex;
+  gap: 1.5rem;
+  padding: 1.5rem;
+  transition: background var(--transition), border-color var(--transition);
+  align-items: center;
+}
+.deal-card:hover {
+  background: rgba(255,255,255,.09);
+  border-color: rgba(255,255,255,.2);
+}
+
+.deal-card-image {
+  width: 120px;
+  flex-shrink: 0;
+  aspect-ratio: 1;
+  border-radius: var(--radius-sm);
+  overflow: hidden;
+  background: rgba(255,255,255,.08);
+}
+.deal-card-image img { width: 100%; height: 100%; object-fit: cover; }
+
+.deal-card-body { flex: 1; }
+.deal-card-brand {
+  font-size: .75rem;
+  font-weight: 500;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: rgba(255,255,255,.55);
+  margin-bottom: .25rem;
+}
+.deal-card-name {
+  font-size: 1rem;
+  font-weight: 600;
+  line-height: 1.3;
+  color: #fff;
+  margin-bottom: .625rem;
+}
+
+.deal-price {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  margin-bottom: .75rem;
+}
+.deal-price-current {
+  font-size: 1.375rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+.deal-price-original {
+  font-size: .875rem;
+  color: rgba(255,255,255,.45);
+  text-decoration: line-through;
+}
+
+/* Countdown */
+.deal-countdown {
+  display: flex;
+  gap: .5rem;
+  margin-bottom: 1rem;
+}
+.countdown-unit {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  background: rgba(255,255,255,.1);
+  border-radius: var(--radius-sm);
+  padding: .375rem .5rem;
+  min-width: 40px;
+}
+.countdown-num {
+  font-size: 1rem;
+  font-weight: 700;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+.countdown-label {
+  font-size: .625rem;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  color: rgba(255,255,255,.55);
+  margin-top: .125rem;
+}
+
+.deal-save-badge {
+  display: inline-block;
+  padding: .25rem .625rem;
+  background: var(--color-accent);
+  border-radius: var(--radius-pill);
+  font-size: .75rem;
+  font-weight: 700;
+  color: #fff;
+  margin-bottom: .75rem;
+}
+
+.deal-progress-label {
+  display: flex;
+  justify-content: space-between;
+  font-size: .75rem;
+  color: rgba(255,255,255,.55);
+  margin-bottom: .375rem;
+}
+.deal-progress-bar {
+  height: 6px;
+  background: rgba(255,255,255,.15);
+  border-radius: var(--radius-pill);
+  overflow: hidden;
+  margin-bottom: .875rem;
+}
+.deal-progress-fill {
+  height: 100%;
+  background: linear-gradient(90deg, var(--color-accent), #ff8c6b);
+  border-radius: var(--radius-pill);
+  transition: width .8s ease;
+}
+
+.btn-deal {
+  background: var(--color-accent);
+  color: #fff;
+  padding: .625rem 1.375rem;
+  border-radius: var(--radius-pill);
+  font-size: .875rem;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition);
+  display: inline-block;
+}
+.btn-deal:hover { background: var(--color-accent-dark); transform: translateY(-1px); }
+
+/* =========================================================
+   BANNER STRIP
+   ========================================================= */
+.banner-strip {
+  background: var(--color-bg-2);
+  padding: 3rem 1.5rem;
+}
+.banner-strip-inner {
+  max-width: var(--max-w);
+  margin: 0 auto;
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 1.5rem;
+}
+
+.promo-banner {
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  position: relative;
+  aspect-ratio: 16/9;
+  display: flex;
+  align-items: flex-end;
+}
+.promo-banner img {
+  position: absolute;
+  inset: 0;
+  width: 100%; height: 100%;
+  object-fit: cover;
+  transition: transform 400ms ease;
+}
+.promo-banner:hover img { transform: scale(1.04); }
+
+.promo-banner-content {
+  position: relative;
+  z-index: 1;
+  padding: 1.25rem;
+  background: linear-gradient(to top, rgba(0,0,0,.7) 0%, transparent 100%);
+  width: 100%;
+}
+.promo-banner-eyebrow {
+  font-size: .75rem;
+  font-weight: 600;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .25rem;
+}
+.promo-banner-title {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: #fff;
+  line-height: 1.2;
+  margin-bottom: .5rem;
+}
+.promo-banner-link {
+  font-size: .8125rem;
+  color: rgba(255,255,255,.8);
+  font-weight: 500;
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  transition: color var(--transition), gap var(--transition);
+}
+.promo-banner:hover .promo-banner-link { color: #fff; gap: .625rem; }
+
+/* =========================================================
+   EDITORIAL / JOURNAL
+   ========================================================= */
+.editorial-section { background: var(--color-surface); }
+
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.5fr 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.article-card {
+  background: var(--color-bg);
+  border-radius: var(--radius-md);
+  overflow: hidden;
+  border: 1.5px solid var(--color-border);
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.article-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
+
+.article-card-image {
+  aspect-ratio: 16/10;
+  overflow: hidden;
+}
+.article-card-image img {
+  width: 100%; height: 100%;
+  object-fit: cover;
+  transition: transform 400ms ease;
+}
+.article-card:hover .article-card-image img { transform: scale(1.04); }
+
+.article-card-body {
+  padding: 1.375rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+.article-card-tag {
+  display: inline-block;
+  font-size: .75rem;
+  font-weight: 600;
+  letter-spacing: .08em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .625rem;
+}
+.article-card-title {
+  font-family: var(--font-display);
+  font-size: 1.125rem;
+  font-weight: 700;
+  line-height: 1.35;
+  color: var(--color-brand);
+  margin-bottom: .625rem;
+}
+.article-card.featured .article-card-title { font-size: 1.4375rem; }
+.article-card-excerpt {
+  font-size: .9rem;
+  color: var(--color-text-muted);
+  line-height: 1.65;
+  flex: 1;
+  margin-bottom: 1rem;
+}
+.article-card-meta {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  margin-top: auto;
+}
+.article-card-author { font-weight: 500; }
+
+/* =========================================================
+   TRUST STRIP
+   ========================================================= */
+.trust-strip {
+  background: var(--color-bg-2);
+  padding: 2.5rem 1.5rem;
+  border-top: 1px solid var(--color-border);
+  border-bottom: 1px solid var(--color-border);
+}
+.trust-strip-inner {
+  max-width: var(--max-w);
+  margin: 0 auto;
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 1.5rem;
+  text-align: center;
+}
+.trust-item { display: flex; flex-direction: column; align-items: center; gap: .625rem; }
+.trust-icon {
+  width: 52px; height: 52px;
+  background: var(--color-brand);
+  color: #fff;
+  border-radius: var(--radius-md);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.trust-title { font-weight: 700; font-size: .9375rem; }
+.trust-desc { font-size: .8125rem; color: var(--color-text-muted); }
+
+/* =========================================================
+   NEWSLETTER
+   ========================================================= */
+.newsletter-section {
+  background: linear-gradient(135deg, #0f3460 0%, #1a1a2e 100%);
+  padding: 5rem 1.5rem;
+  text-align: center;
+  color: #fff;
+}
+.newsletter-inner { max-width: 560px; margin: 0 auto; }
+
+.newsletter-kicker {
+  display: block;
+  font-size: .8125rem;
+  font-weight: 600;
+  letter-spacing: .12em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .75rem;
+}
+.newsletter-title {
+  font-family: var(--font-display);
+  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
+  font-weight: 700;
+  margin-bottom: 1rem;
+  line-height: 1.15;
+}
+.newsletter-desc {
+  font-size: 1rem;
+  color: rgba(255,255,255,.7);
+  margin-bottom: 2rem;
+  line-height: 1.65;
+}
+
+.newsletter-form {
+  display: flex;
+  max-width: 480px;
+  margin: 0 auto 1rem;
+  background: rgba(255,255,255,.08);
+  border: 1.5px solid rgba(255,255,255,.2);
+  border-radius: var(--radius-pill);
+  padding: .375rem .375rem .375rem 1.25rem;
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+.newsletter-form:focus-within {
+  border-color: var(--color-focus);
+  box-shadow: 0 0 0 3px rgba(26,107,255,.25);
+}
+.newsletter-form input {
+  flex: 1;
+  background: none;
+  border: none;
+  outline: none;
+  font-size: .9375rem;
+  color: #fff;
+  min-width: 0;
+}
+.newsletter-form input::placeholder { color: rgba(255,255,255,.5); }
+.newsletter-form .btn-primary {
+  flex-shrink: 0;
+  padding: .6875rem 1.5rem;
+  font-size: .875rem;
+}
+.newsletter-privacy {
+  font-size: .8125rem;
+  color: rgba(255,255,255,.45);
+}
+
+/* Status message */
+.newsletter-status {
+  margin-top: .875rem;
+  font-size: .9rem;
+  min-height: 1.4em;
+}
+.newsletter-status.success { color: #6ee7b7; }
+.newsletter-status.error   { color: #fca5a5; }
+
+/* =========================================================
+   FOOTER
+   ========================================================= */
+.site-footer {
+  background: var(--color-brand);
+  color: rgba(255,255,255,.8);
+  padding: 4rem 1.5rem 2rem;
+}
+.footer-inner {
+  max-width: var(--max-w);
+  margin: 0 auto;
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr 1fr;
+  gap: 3rem;
+}
+
+.footer-brand .site-logo {
+  color: #fff;
+  font-size: 1.375rem;
+  margin-bottom: 1rem;
+}
+.footer-brand-desc {
+  font-size: .9rem;
+  line-height: 1.7;
+  max-width: 280px;
+  color: rgba(255,255,255,.6);
+  margin-bottom: 1.5rem;
+}
+.footer-social {
+  display: flex;
+  gap: .625rem;
+}
+.social-btn {
+  width: 38px; height: 38px;
+  border-radius: var(--radius-sm);
+  background: rgba(255,255,255,.08);
+  color: rgba(255,255,255,.7);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  transition: background var(--transition), color var(--transition);
+}
+.social-btn:hover { background: var(--color-accent); color: #fff; }
+
+.footer-col-title {
+  font-size: .875rem;
+  font-weight: 700;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  color: #fff;
+  margin-bottom: 1.25rem;
+}
+.footer-links { display: flex; flex-direction: column; gap: .625rem; }
+.footer-links a {
+  font-size: .9rem;
+  color: rgba(255,255,255,.6);
+  transition: color var(--transition);
+}
+.footer-links a:hover { color: #fff; }
+
+.footer-bottom {
+  max-width: var(--max-w);
+  margin: 3rem auto 0;
+  padding-top: 1.5rem;
+  border-top: 1px solid rgba(255,255,255,.1);
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  flex-wrap: wrap;
+}
+.footer-copyright { font-size: .8125rem; color: rgba(255,255,255,.4); }
+.footer-legal {
+  display: flex;
+  gap: 1.5rem;
+}
+.footer-legal a { font-size: .8125rem; color: rgba(255,255,255,.4); transition: color var(--transition); }
+.footer-legal a:hover { color: rgba(255,255,255,.8); }
+
+/* =========================================================
+   CART DRAWER
+   ========================================================= */
+.cart-overlay {
+  position: fixed;
