/* main.js — HAVEN ecommerce interactions */
'use strict';

/* =========================================================
   CART STATE
   ========================================================= */
const cart = {
  items: [],
  get count() { return this.items.reduce((s, i) => s + i.qty, 0); },
  get subtotal() { return this.items.reduce((s, i) => s + i.price * i.qty, 0); },

  add(product) {
    const existing = this.items.find(i => i.id === product.id);
    if (existing) { existing.qty++; }
    else { this.items.push({ ...product, qty: 1 }); }
    this.persist();
    renderCart();
    updateCartCount();
    showToast(`"${product.name}" added to cart`);
  },

  remove(id) {
    this.items = this.items.filter(i => i.id !== id);
    this.persist();
    renderCart();
    updateCartCount();
  },

  persist() {
    try { localStorage.setItem('haven_cart', JSON.stringify(this.items)); } catch {}
  },

  hydrate() {
    try {
      const saved = JSON.parse(localStorage.getItem('haven_cart') || '[]');
      if (Array.isArray(saved)) this.items = saved;
    } catch {}
  }
};

/* =========================================================
   PRODUCT DATA
   ========================================================= */
const products = [
  {
