  },
  {
    id: 'p4',
    brand: 'Luminary',
    name: 'Wide-Leg Linen Trousers',
    price: 98,
    originalPrice: 135,
    rating: 4.5,
    reviews: 156,
    badge: 'Sale',
    image: 'https://images.unsplash.com/photo-1594938298603-c8148c4b4d7b?w=480&q=80',
