  },
];

/* =========================================================
   RENDER PRODUCTS
   ========================================================= */
function starsHTML(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  const starSVG = (type) => {
    if (type === 'full')  return `<svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg>`;
    if (type === 'half')  return `<svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2v15.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01zm0 0l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77"/></svg>`;
    return `<svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg>`;
  };
  return `<span class="stars" aria-hidden="true">${'full'.repeat ? Array(full).fill(starSVG('full')).join('') + Array(half).fill(starSVG('half')).join('') + Array(empty).fill(starSVG('empty')).join('') : ''}</span>`;
}

function productCardHTML(p) {
  const isWishlisted = getWishlist().includes(p.id);
  const priceHTML = p.originalPrice
    ? `<span class="price-current is-sale">$${p.price}</span><span class="price-original" aria-label="Original price $${p.originalPrice}">$${p.originalPrice}</span>`
    : `<span class="price-current">$${p.price}</span>`;
  const badgeHTML = p.badge
    ? `<div class="product-card-badges"><span class="badge badge-${p.badge.toLowerCase()}">${p.badge}</span></div>`
    : '';
  const stars = Array(Math.floor(p.rating)).fill(
    `<svg aria-hidden="true" width="12" height="12" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg>`
  ).join('');

  return `
    <article class="product-card" data-product-id="${p.id}" data-category="${p.category}">
      <div class="product-card-image">
        ${badgeHTML}
        <img src="${p.image}" alt="${p.name}" loading="lazy" width="480" height="640">
        <button class="product-card-wishlist" aria-label="${isWishlisted ? 'Remove' : 'Add'} ${p.name} from wishlist" aria-pressed="${isWishlisted}" data-wishlist="${p.id}">
          <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="${isWishlisted ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
          </svg>
        </button>
      </div>
      <div class="product-card-body">
        <span class="product-card-brand">${p.brand}</span>
        <h3 class="product-card-name"><a href="#" aria-label="${p.name} — ${p.brand}">${p.name}</a></h3>
        <div class="product-card-rating">
          <span class="stars" aria-hidden="true">${stars}</span>
          <span aria-label="${p.rating} out of 5 stars, ${p.reviews} reviews">${p.rating} (${p.reviews})</span>
        </div>
      </div>
      <div class="product-card-footer">
        <div class="product-price">${priceHTML}</div>
        <button class="add-to-cart-btn" aria-label="Add ${p.name} to cart" data-add="${p.id}">
          <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M6 2L3 6v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/>
            <path d="M16 10a4 4 0 01-8 0"/>
          </svg>
        </button>
      </div>
    </article>`;
}

function renderProducts(filter = 'all') {
  const grid = document.getElementById('product-grid');
  if (!grid) return;
  const filtered = filter === 'all' ? products : products.filter(p => p.category === filter);
  grid.innerHTML = filtered.map(productCardHTML).join('');
}

/* =========================================================
   WISHLIST
   ========================================================= */
function getWishlist() {
  try { return JSON.parse(localStorage.getItem('haven_wishlist') || '[]'); } catch { return []; }
}
function saveWishlist(list) {
  try { localStorage.setItem('haven_wishlist', JSON.stringify(list)); } catch {}
}
function toggleWishlist(id, btn) {
  const list = getWishlist();
  const idx = list.indexOf(id);
  const product = products.find(p => p.id === id);
  const name = product ? product.name : 'item';
  if (idx === -1) {
    list.push(id);
    btn.setAttribute('aria-pressed', 'true');
    btn.setAttribute('aria-label', `Remove ${name} from wishlist`);
    btn.querySelector('svg').setAttribute('fill', 'currentColor');
    showToast(`"${name}" added to wishlist`);
  } else {
    list.splice(idx, 1);
    btn.setAttribute('aria-pressed', 'false');
    btn.setAttribute('aria-label', `Add ${name} to wishlist`);
    btn.querySelector('svg').setAttribute('fill', 'none');
    showToast(`"${name}" removed from wishlist`);
  }
  saveWishlist(list);
}

/* =========================================================
   CART DRAWER
   ========================================================= */
function updateCartCount() {
  const badge = document.getElementById('cart-count');
  const count = cart.count;
  if (badge) {
    badge.textContent = count;
    badge.hidden = count === 0;
    const btn = badge.closest('button');
    if (btn) btn.setAttribute('aria-label', `Shopping cart, ${count} item${count !== 1 ? 's' : ''}`);
  }
}

function renderCart() {
  const body   = document.getElementById('cart-body');
  const footer = document.getElementById('cart-footer');
  if (!body || !footer) return;

  if (cart.items.length === 0) {
    body.innerHTML = `
      <div class="cart-empty" aria-live="polite">
        <svg aria-hidden="true" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
          <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
          <path d="M1 1h4l2.68 13.39a2 2 0 001.99 1.61h9.72a2 2 0 001.98-1.71L23 6H6"/>
        </svg>
        <p>Your cart is empty.<br>Start adding some items!</p>
      </div>`;
    footer.hidden = true;
    return;
  }

  body.innerHTML = cart.items.map(item => `
    <div class="cart-item" data-cart-item="${item.id}">
      <div class="cart-item-image">
        <img src="${item.image}" alt="${item.name}" loading="lazy" width="72" height="88">
      </div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-variant">${item.brand} · Qty ${item.qty}</div>
        <div class="cart-item-price">$${(item.price * item.qty).toFixed(2)}</div>
        <button class="cart-item-remove" data-remove="${item.id}" aria-label="Remove ${item.name} from cart">Remove</button>
      </div>
    </div>`).join('');

  document.getElementById('cart-subtotal-value').textContent = `$${cart.subtotal.toFixed(2)}`;
  footer.hidden = false;
}

function openCart() {
  const overlay = document.getElementById('cart-overlay');
  const drawer  = document.getElementById('cart-drawer');
  overlay.classList.add('is-open');
  drawer.classList.add('is-open');
  drawer.setAttribute('aria-hidden', 'false');
  document.getElementById('cart-close-btn').focus();
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  const overlay = document.getElementById('cart-overlay');
  const drawer  = document.getElementById('cart-drawer');
  overlay.classList.remove('is-open');
  drawer.classList.remove('is-open');
  drawer.setAttribute('aria-hidden', 'true');
  document.getElementById('cart-btn').focus();
  document.body.style.overflow = '';
}

/* =========================================================
   TOAST NOTIFICATIONS
   ========================================================= */
function showToast(message) {
  const container = document.getElementById('toast-container');
  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  toast.innerHTML = `
    <svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
      <path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>
    </svg>
    <span>${message}</span>`;
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.add('removing');
    toast.addEventListener('animationend', () => toast.remove(), { once: true });
  }, 3000);
}

/* =========================================================
   COUNTDOWN TIMER
   ========================================================= */
function startCountdowns() {
  const timers = document.querySelectorAll('[data-countdown]');
  timers.forEach(el => {
    const endStr = el.dataset.countdown;
    const endTime = new Date(endStr).getTime();
    function tick() {
      const diff = endTime - Date.now();
      if (diff <= 0) { el.textContent = 'Expired'; return; }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      const hEl = el.querySelector('[data-unit="h"]');
      const mEl = el.querySelector('[data-unit="m"]');
      const sEl = el.querySelector('[data-unit="s"]');
      if (hEl) hEl.textContent = String(h).padStart(2, '0');
      if (mEl) mEl.textContent = String(m).padStart(2, '0');
      if (sEl) sEl.textContent = String(s).padStart(2, '0');
    }
    tick();
    setInterval(tick, 1000);
    el.setAttribute('aria-label', `Deal ends in ${el.innerText}`);
  });
}

/* =========================================================
   FILTER BAR
   ========================================================= */
function initFilters() {
  const bar = document.getElementById('filter-bar');
  if (!bar) return;
  bar.addEventListener('click', e => {
    const btn = e.target.closest('.filter-btn');
    if (!btn) return;
    bar.querySelectorAll('.filter-btn').forEach(b => {
      b.setAttribute('aria-pressed', 'false');
    });
    btn.setAttribute('aria-pressed', 'true');
    renderProducts(btn.dataset.filter);
  });
}

/* =========================================================
   NEWSLETTER FORM
   ========================================================= */
function initNewsletter() {
  const form = document.getElementById('newsletter-form');
  const status = document.getElementById('newsletter-status');
  if (!form || !status) return;

  form.addEventListener('submit', async e => {
    e.preventDefault();
    const input = form.querySelector('input[type="email"]');
    const email = input.value.trim();
    if (!email) {
      status.textContent = 'Please enter your email address.';
      status.className = 'newsletter-status error';
      input.focus();
      return;
    }
    // Simulate async subscription
    await new Promise(r => setTimeout(r, 600));
    status.textContent = `You're in! We'll be in touch at ${email}.`;
    status.className = 'newsletter-status success';
    form.reset();
  });
}

/* =========================================================
   MOBILE MENU
   ========================================================= */
function initMobileMenu() {
  const toggle = document.getElementById('menu-toggle');
  const nav    = document.getElementById('primary-nav');
  if (!toggle || !nav) return;

  toggle.addEventListener('click', () => {
    const expanded = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', String(!expanded));
    nav.classList.toggle('is-open', !expanded);
  });

  // Close on Escape
  nav.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      toggle.setAttribute('aria-expanded', 'false');
      nav.classList.remove('is-open');
      toggle.focus();
    }
  });
}

/* =========================================================
   SEARCH (accessible)
   ========================================================= */
function initSearch() {
  const form = document.getElementById('search-form');
  if (!form) return;
  form.addEventListener('submit', e => {
    e.preventDefault();
    const q = form.querySelector('input').value.trim();
    if (q) showToast(`Searching for "${q}"…`);
  });
}

/* =========================================================
   GLOBAL EVENT DELEGATION
   ========================================================= */
document.addEventListener('click', e => {
  // Add to cart
  const addBtn = e.target.closest('[data-add]');
  if (addBtn) {
    const id = addBtn.dataset.add;
    const product = products.find(p => p.id === id);
    if (product) cart.add(product);
    return;
  }

  // Wishlist toggle
  const wishBtn = e.target.closest('[data-wishlist]');
  if (wishBtn) {
    toggleWishlist(wishBtn.dataset.wishlist, wishBtn);
    return;
  }

  // Remove from cart
  const removeBtn = e.target.closest('[data-remove]');
  if (removeBtn) {
    cart.remove(removeBtn.dataset.remove);
    return;
  }

  // Open cart
  if (e.target.closest('#cart-btn')) { openCart(); return; }

  // Close cart
  if (e.target.closest('#cart-close-btn') || e.target.closest('#cart-overlay')) {
    closeCart();
    return;
  }
});

// Close cart on Escape
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    const drawer = document.getElementById('cart-drawer');
    if (drawer && drawer.classList.contains('is-open')) closeCart();
  }
});

/* =========================================================
   INIT
   ========================================================= */
document.addEventListener('DOMContentLoaded', () => {
  cart.hydrate();
  renderProducts();
  renderCart();
  updateCartCount();
  startCountdowns();
  initFilters();
  initNewsletter();
  initMobileMenu();
  initSearch();
});

