+   ========================================================= */
+function initMobileMenu() {
+  const toggle = document.getElementById('menu-toggle');
+  const nav    = document.getElementById('primary-nav');
+  if (!toggle || !nav) return;
+
+  toggle.addEventListener('click', () => {
+    const expanded = toggle.getAttribute('aria-expanded') === 'true';
+    toggle.setAttribute('aria-expanded', String(!expanded));
+    nav.classList.toggle('is-open', !expanded);
+  });
+
+  // Close on Escape
+  nav.addEventListener('keydown', e => {
+    if (e.key === 'Escape') {
+      toggle.setAttribute('aria-expanded', 'false');
+      nav.classList.remove('is-open');
+      toggle.focus();
+    }
+  });
+}
+
+/* =========================================================
+   SEARCH (accessible)
+   ========================================================= */
+function initSearch() {
+  const form = document.getElementById('search-form');
+  if (!form) return;
+  form.addEventListener('submit', e => {
+    e.preventDefault();
+    const q = form.querySelector('input').value.trim();
+    if (q) showToast(`Searching for "${q}"…`);
+  });
+}
+
+/* =========================================================
+   GLOBAL EVENT DELEGATION
+   ========================================================= */
+document.addEventListener('click', e => {
+  // Add to cart
+  const addBtn = e.target.closest('[data-add]');
+  if (addBtn) {
+    const id = addBtn.dataset.add;
+    const product = products.find(p => p.id === id);
+    if (product) cart.add(product);
+    return;
+  }
+
+  // Wishlist toggle
+  const wishBtn = e.target.closest('[data-wishlist]');
+  if (wishBtn) {
+    toggleWishlist(wishBtn.dataset.wishlist, wishBtn);
+    return;
+  }
+
+  // Remove from cart
+  const removeBtn = e.target.closest('[data-remove]');
+  if (removeBtn) {
+    cart.remove(removeBtn.dataset.remove);
+    return;
+  }
+
+  // Open cart
+  if (e.target.closest('#cart-btn')) { openCart(); return; }
+
+  // Close cart
+  if (e.target.closest('#cart-close-btn') || e.target.closest('#cart-overlay')) {
+    closeCart();
+    return;
+  }
+});
+
+// Close cart on Escape
+document.addEventListener('keydown', e => {
+  if (e.key === 'Escape') {
+    const drawer = document.getElementById('cart-drawer');
+    if (drawer && drawer.classList.contains('is-open')) closeCart();
+  }
+});
+
+/* =========================================================
+   INIT
+   ========================================================= */
+document.addEventListener('DOMContentLoaded', () => {
+  cart.hydrate();
+  renderProducts();
+  renderCart();
+  updateCartCount();
+  startCountdowns();
+  initFilters();
+  initNewsletter();
+  initMobileMenu();
+  initSearch();
+});
+
')

